    )
    palette = sorted(color for color, count in freq.items() if count >= 5)

    # Recover the repeating order from adjacent cells.
    transitions = Counter()
    for r in range(3, h):
        for c in range(3, w - 1):
            a, b = grid[r][c], grid[r][c + 1]
            if a in palette and b in palette:
                transitions[a, b] += 1

    if len(palette) > 1:
        cycle = max(
