    phases = []
    for r in range(h):
        votes = Counter()
        for c in range(3, w):
            value = grid[r][c]
            if value in index:
                votes[(index[value] - c) % n] += 1
        phases.append(votes.most_common(1)[0][0] if votes else r % n)

